function admin_head(string $title):void{require_admin();$cur=basename($_SERVER['PHP_SELF']??'index.php');echo '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#05080A"><title>'.e($title).' | أبشر</title><link rel="stylesheet" href="../assets/admin-v7.css"></head><body class="admin-body"><aside class="admin-side"><a class="admin-brand" href="index.php"><span>A</span><div><b>أبشر</b><small>CONTROL CENTER</small></div></a><nav>';
$links=[['index.php','لوحة القيادة','⌂'],['products.php','المنتجات','▦'],['quotes.php','طلبات الأسعار','▤'],['quality.php','جودة البيانات','◆'],['settings.php','الإعدادات','⚙'],['../index.php','عرض الموقع','↗']];foreach($links as[$href,$label,$icon]){$active=$cur===$href?' active':'';echo '<a class="'.$active.'" href="'.e($href).'"><i>'.$icon.'</i><span>'.e($label).'</span></a>';}echo '</nav><a class="logout" href="logout.php">تسجيل الخروج</a></aside><div class="admin-main"><header class="admin-top"><div><span class="admin-kicker">ABSHAR OPERATIONS</span><h1>'.e($title).'</h1></div><div class="operator"><span class="status-dot"></span><b>'.e((string)($_SESSION['admin_user']??'Admin')).'</b></div></header><main class="admin-content">';}
function admin_foot():void{echo '</main><footer class="admin-foot">ABSHAR Smart Catalog · Operations Console</footer></div></body></html>';}
function metric(string $label,string $value,string $note='',string $tone='blue'):void{echo '<article class="metric-card tone-'.e($tone).'"><span>'.e($label).'</span><strong>'.e($value).'</strong><small>'.e($note).'</small></article>';}
